pub struct OrderService<P: OrderPort, S: StockPort> { pool: PgPool, orders: P, stock: S }

impl<P: OrderPort, S: StockPort> OrderService<P, S> {
    pub async fn place(&self, req: OrderRequest) -> Result<i64, sqlx::Error> {
        let mut tx = self.pool.begin().await?;               // rollback on drop
        let id = self.orders.insert(&mut tx, &req).await?;
        self.stock.reserve(&mut tx, id).await?;
        tx.commit().await?;
        Ok(id)
    }
}
